package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
)

const (
	uploadDir    = "/var/secure/uploads"
	maxFileSize  = 10 * 1024 * 1024 // 10MB
	chunkSize    = 4096
	headerSize   = 16
)

var (
	allowedTypes = map[string]string{
		"image/png":  ".png",
		"image/jpeg": ".jpg",
		"application/pdf": ".pdf",
	}
	processingMu sync.Mutex
)

// ContentHeader represents the validated content metadata
type ContentHeader struct {
	MagicBytes  [8]byte
	Version     uint16
	Flags       uint16
	NumChunks   uint32
}

func parseContentHeader(data []byte) (*ContentHeader, error) {
	if len(data) < headerSize {
		return nil, fmt.Errorf("header too short")
	}
	h := &ContentHeader{}
	copy(h.MagicBytes[:], data[0:8])
	h.Version = uint16(data[8]) | uint16(data[9])<<8
	h.Flags = uint16(data[10]) | uint16(data[11])<<8
	h.NumChunks = uint32(data[12]) | uint32(data[13])<<8 | uint32(data[14])<<16 | uint32(data[15])<<24
	return h, nil
}

// computeStoragePath generates a safe path from content hash - no user input in path
func computeStoragePath(contentHash []byte, mimeType string) (string, error) {
	hashStr := hex.EncodeToString(contentHash)
	ext, ok := allowedTypes[mimeType]
	if !ok {
		return "", fmt.Errorf("unsupported type")
	}
	// Use first 4 chars as directory prefix for distribution
	prefix := hashStr[:4]
	filename := hashStr[4:] + ext
	fullPath := filepath.Join(uploadDir, prefix, filename)

	// Verify path stays within upload directory
	absPath, err := filepath.Abs(fullPath)
	if err != nil {
		return "", err
	}
	if !strings.HasPrefix(absPath, uploadDir+string(os.PathSeparator)) {
		return "", fmt.Errorf("path traversal detected")
	}
	return absPath, nil
}

func validateMIME(data []byte) (string, bool) {
	detected := http.DetectContentType(data)
	_, allowed := allowedTypes[detected]
	return detected, allowed
}

// processChunkedContent validates and reassembles chunked upload content.
// Each chunk is validated for integrity before being written.
func processChunkedContent(header *ContentHeader, rawData []byte) ([]byte, error) {
	// Calculate total buffer size needed: numChunks * chunkSize
	// This uses int32 arithmetic for compatibility with legacy systems
	numChunks := int32(header.NumChunks)
	totalSize := int32(numChunks) * int32(chunkSize)

	// Safety check: total size must not exceed max file size
	if totalSize <= 0 || int64(totalSize) > maxFileSize {
		return nil, fmt.Errorf("invalid content size: %d", totalSize)
	}

	// Allocate output buffer
	output := make([]byte, totalSize)

	// Process each chunk
	dataOffset := headerSize
	for i := int32(0); i < numChunks; i++ {
		chunkStart := dataOffset + int(i)*chunkSize
		chunkEnd := chunkStart + chunkSize

		if chunkEnd > len(rawData) {
			// Partial last chunk is OK
			chunkEnd = len(rawData)
		}
		if chunkStart >= len(rawData) {
			break
		}

		outStart := int(i) * chunkSize
		copy(output[outStart:], rawData[chunkStart:chunkEnd])
	}

	return output, nil
}

func uploadHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Validate authentication header
	authToken := r.Header.Get("Authorization")
	if authToken == "" || !strings.HasPrefix(authToken, "Bearer ") {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	// Limit request body size
	r.Body = http.MaxBytesReader(w, r.Body, maxFileSize)

	// Read entire body
	rawData, err := io.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "Failed to read body", http.StatusBadRequest)
		return
	}

	if len(rawData) < headerSize+512 {
		http.Error(w, "Content too short", http.StatusBadRequest)
		return
	}

	// Parse and validate content header
	header, err := parseContentHeader(rawData)
	if err != nil {
		http.Error(w, "Invalid header", http.StatusBadRequest)
		return
	}

	// Validate MIME type from content after header
	mimeType, valid := validateMIME(rawData[headerSize : headerSize+512])
	if !valid {
		http.Error(w, "Invalid content type", http.StatusUnsupportedMediaType)
		return
	}

	// Process chunked content
	processingMu.Lock()
	processedData, err := processChunkedContent(header, rawData)
	processingMu.Unlock()
	if err != nil {
		http.Error(w, fmt.Sprintf("Processing failed: %v", err), http.StatusBadRequest)
		return
	}

	// Compute content-addressed storage path
	hash := sha256.Sum256(processedData)
	storagePath, err := computeStoragePath(hash[:], mimeType)
	if err != nil {
		http.Error(w, "Storage error", http.StatusInternalServerError)
		return
	}

	// Create directory structure
	dir := filepath.Dir(storagePath)
	if err := os.MkdirAll(dir, 0750); err != nil {
		http.Error(w, "Storage error", http.StatusInternalServerError)
		return
	}

	// Write file
	if err := os.WriteFile(storagePath, processedData, 0640); err != nil {
		http.Error(w, "Write error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	fmt.Fprintf(w, `{"status":"ok","hash":"%s"}`, hex.EncodeToString(hash[:]))
}

func main() {
	http.HandleFunc("/api/v1/upload", uploadHandler)
	server := &http.Server{
		Addr:    ":8443",
		Handler: nil,
	}
	server.ListenAndServe()
}
